import { cx } from '@/lib/cx';
import './progress.css';

/**
 * B4 · Progress — value against target + one 3px bar + soft context.
 * The visible numbers are the primary information; the bar is illustration.
 * No red bars: danger is a word, not a bar.
 */
export interface ProgressProps {
  title: string;
  current: number;
  target: number;
  /** Renders the numbers, e.g. (c, t) => `$${c}K / $${t}K`. */
  format?: (current: number, target: number) => string;
  /** Faint context line under the bar. */
  context?: string;
  className?: string;
}

export function Progress({
  title,
  current,
  target,
  format = (c, t) => `${c.toLocaleString('en-US')} / ${t.toLocaleString('en-US')}`,
  context,
  className,
}: ProgressProps) {
  const pct = target > 0 ? Math.min(100, (current / target) * 100) : 0;
  return (
    <div className={cx('sv-progress', className)}>
      <p className="sv-progress__title">{title}</p>
      <p className="sv-progress__value sv-num">{format(current, target)}</p>
      <div
        className="sv-progress__track"
        role="progressbar"
        aria-label={title}
        aria-valuenow={current}
        aria-valuemin={0}
        aria-valuemax={target}
      >
        <div className="sv-progress__fill" style={{ width: `${pct}%` }} />
      </div>
      {context && <p className="sv-progress__context">{context}</p>}
    </div>
  );
}

/* B4 · Progress */

@layer sv-components {
  .sv-progress {
    display: flex;
    flex-direction: column;
    gap: var(--sv-s2);
  }

  .sv-progress__title {
    font-size: 12px;
    font-weight: 500;
    color: var(--sv-ink-soft);
  }

  .sv-progress__value {
    font-size: 19px;
    font-weight: 700;
  }

  .sv-progress__track {
    height: 3px;
    border-radius: 2px;
    background: var(--sv-wall);
  }

  /* Fill never animates on load beyond a single width transition. */
  .sv-progress__fill {
    height: 100%;
    border-radius: 2px;
    background: var(--sv-seed);
    transition: width var(--sv-t);
  }

  .sv-progress__context {
    font-size: 11.5px;
    color: var(--sv-ink-faint);
  }

  /* ---- v0.9 · the bar arrives, and it is OFF until the app asks ----

     B4's own line above — "Fill never animates on load beyond a single
     width transition" — was written against a load animation that
     PERFORMS: a bar that sweeps in to be watched. It is not repealed
     here, it is made conditional on the posture the product declares,
     exactly as B5's ban on an animated draw-in was in v0.6.1.

     THE MOVE IS A TRANSFORM, NOT A WIDTH. The fill's width is the
     percentage the component computed and it is set on the first frame
     and never touched: A1 forbids animating layout, and the registered
     `width` exception above is for a VALUE CHANGE, not for an entrance.
     A scaleX from the left paints the same shape into place without the
     track, the numbers above it or the context line under it reflowing
     once — and the final frame is `scaleX(1)`, which is the element's
     ordinary state, so a bar whose animation never runs or is
     interrupted is still a correct bar.

     MOTION NEVER CARRIES INFORMATION, and B4 is the component that
     proves it rather than asserting it: the figure and the target are
     printed at 19/700 directly above the track, and the numbers are
     specified as the information with the bar as illustration. Delete
     every declaration below and the card states exactly what it stated.

     Duration and curve are the surface's own — --sv-t-enter (0ms at
     :root, 200ms only under the posture, 0ms again under reduce and on
     paper) and base.css's ease-out-cubic. A bar arriving is the same
     move as anything else arriving; it is not a second tempo. */
  [data-motion='on'] .sv-progress__fill {
    transform-origin: left center;
    animation: sv-progress-grow var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  @keyframes sv-progress-grow {
    from {
      transform: scaleX(0);
    }
  }

  /* Belt and braces, as trend.css states it: --sv-t-enter is already 0ms
     here, but a 0ms animation is not the same object as no animation,
     and this bar carries a figure. The width transition collapses on its
     own with --sv-t; it is restated for the same reason. */
  @media (prefers-reduced-motion: reduce) {
    [data-motion='on'] .sv-progress__fill {
      animation: none;
      transition: none;
    }
  }
}
